INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 2, 'theory', 'Quiz: the transistor and digital abstraction');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 2, 0, 'What turns pure silicon into an n-type semiconductor?', '["Heating to a high temperature", "A boron impurity: it creates a hole", "A group-five impurity such as arsenic: it adds a free electron", "Exposure to light"]', 2, 'Arsenic has five valence electrons, one of them extra and free to move through the lattice. Boron creates a hole and makes silicon p-type.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 2, 1, 'When is an n-MOS transistor on?', '["When the gate is at one (a high enough voltage)", "When the gate is at zero", "When the drain voltage is higher than the source voltage", "Always, as long as power is applied"]', 0, 'A positive gate voltage creates an n-type channel under the oxide between source and drain. A p-MOS, on the contrary, turns on with a zero on the gate.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 2, 2, 'Which transistors are in series in a CMOS NAND gate?', '["Both p-MOS", "One p-MOS and one n-MOS", "The transistors are not connected at all", "Both n-MOS"]', 3, 'The output must go to ground only when both n-MOS are on, so they are in series. The p-MOS are in parallel: one is enough to pull the output up to one.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 2, 3, 'Suppose VOL = 0.33 V and VIL = 1.35 V. What is the noise margin for zero, NML?', '["0.33 V", "1.02 V", "1.35 V", "1.68 V"]', 1, 'NML = VIL − VOL = 1.35 − 0.33 = 1.02 V. That is how much noise can be added to a zero on its way from driver to receiver while the gate still reads it as zero.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 2, 4, 'How does dynamic power change if the supply voltage is halved at the same frequency and capacitance?', '["It becomes four times smaller", "It becomes half as large", "It does not change", "It becomes eight times smaller"]', 0, 'P = ½ · C · V² · f depends on the square of the voltage: half the V gives a quarter of the P. That is why the supply voltage is lowered with every new technology.');
